<?php require __DIR__.'/includes/db.php'; require __DIR__.'/includes/auth.php'; require_login();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM students WHERE id=?');$s->execute([$id]);$student=$s->fetch();if(!$student)exit('Student not found');$f=$pdo->prepare('SELECT * FROM student_files WHERE student_id=? ORDER BY uploaded_at DESC');$f->execute([$id]);$files=$f->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="admin.css"><title>Student profile</title></head><body><main class="main" style="max-width:1000px;margin:35px auto"><a href="view_students.php">← Back to directory</a><section class="table-card" style="padding:28px;margin-top:20px"><div class="crumb">STUDENT PROFILE</div><h1><?=e($student['name'])?></h1><p><?=e($student['roll_number'])?> · <?=e($student['course'])?></p><p><?=e($student['email'])?></p><a class="add-btn" href="edit_student.php?id=<?=$id?>">Edit profile</a><hr><h2>Uploaded files</h2><?php foreach($files as $file):?><p><a href="file.php?id=<?=$file['id']?>" target="_blank"><?=e($file['original_name'])?></a> · <?=e($file['mime_type'])?> · <?=number_format($file['file_size']/1024,1)?> KB · <?=e($file['file_category'])?></p><?php if(str_starts_with($file['mime_type'],'image/')):?><img src="file.php?id=<?=$file['id']?>" style="max-width:150px;max-height:130px;border-radius:8px"><?php endif?><?php endforeach?><form method="post" action="upload.php" enctype="multipart/form-data" style="margin-top:25px"><input type="hidden" name="student_id" value="<?=$id?>"><label>Upload image/document <input type="file" name="document" accept="image/jpeg,image/png,application/pdf" required></label><select name="category"><option value="document">Document</option><option value="profile">Profile image</option></select><button class="add-btn">Upload file</button></form></section></main></body></html>
